using System.Text.Json;
using Microsoft.AspNetCore.Http;

namespace Example;

/// <summary>Create-user request received by the example endpoint.</summary>
/// <param name="Email">Email address supplied by the caller.</param>
/// <param name="Name">Display name supplied by the caller.</param>
/// <param name="Age">Optional age supplied by the caller.</param>
public sealed record CreateUserRequest(string? Email, string? Name, int? Age);

/// <summary>Accepted create-user payload returned by the example endpoint.</summary>
/// <param name="Email">Email address that passed validation.</param>
/// <param name="Name">Display name that passed validation.</param>
/// <param name="Age">Optional age that passed validation.</param>
public sealed record CreateUserResponse(string Email, string Name, int? Age);

/// <summary>Validates create-user requests.</summary>
public static class Validator
{
    /// <summary>Problem-details key for the email field.</summary>
    public const string EmailField = "email";

    /// <summary>Problem-details key for the name field.</summary>
    public const string NameField = "name";

    /// <summary>Problem-details key for the age field.</summary>
    public const string AgeField = "age";

    /// <summary>User-facing message for an unusable email address.</summary>
    public const string EmailInvalidMessage = "email must be a valid address";

    /// <summary>User-facing message for a missing display name.</summary>
    public const string NameRequiredMessage = "name is required";

    /// <summary>User-facing message for a negative age.</summary>
    public const string AgeNegativeMessage = "age must be non-negative";

    private const char EmailSeparator = '@';

    /// <summary>Validates a create-user request.</summary>
    /// <param name="request">Untrusted request data.</param>
    /// <returns>Validation errors keyed by field name; empty when the request is valid.</returns>
    public static IReadOnlyDictionary<string, string[]> ValidateFields(CreateUserRequest request)
    {
        var errors = new Dictionary<string, string[]>();

        if (string.IsNullOrWhiteSpace(request.Email) || !request.Email.Contains(EmailSeparator))
        {
            errors[EmailField] = [EmailInvalidMessage];
        }

        if (string.IsNullOrWhiteSpace(request.Name))
        {
            errors[NameField] = [NameRequiredMessage];
        }

        if (request.Age is < 0)
        {
            errors[AgeField] = [AgeNegativeMessage];
        }

        return errors;
    }

    /// <summary>Validates a create-user request.</summary>
    /// <param name="request">Untrusted request data.</param>
    /// <returns>Validation errors; empty when the request is valid.</returns>
    public static IReadOnlyList<string> Validate(CreateUserRequest request)
        => ValidateFields(request).Values.SelectMany(messages => messages).ToList();
}

/// <summary>Handles the create-user endpoint and reports invalid input as a problem response.</summary>
public static class CreateUserEndpoint
{
    /// <summary>Problem title used when the request body is absent.</summary>
    public const string MissingBodyTitle = "Missing request body";

    /// <summary>Problem detail used when the request body is absent.</summary>
    public const string MissingBodyDetail = "A JSON create-user request body is required.";

    /// <summary>Problem title used when the request body is not a valid create-user payload.</summary>
    public const string MalformedBodyTitle = "Malformed request body";

    /// <summary>Problem detail used when the request body is not a valid create-user payload.</summary>
    public const string MalformedBodyDetail = "The request body must be a JSON object with email, name, and optional age fields.";

    /// <summary>Problem title used when the payload fails validation.</summary>
    public const string InvalidRequestTitle = "Invalid create-user request";

    /// <summary>JSON contract used to read the request body.</summary>
    public static readonly JsonSerializerOptions BodyJsonOptions = new(JsonSerializerDefaults.Web);

    /// <summary>Handles a create-user request body.</summary>
    /// <param name="body">Raw JSON body received by the endpoint.</param>
    /// <returns>200 with the accepted payload; 400 problem details for missing, malformed, or invalid input.</returns>
    public static IResult Handle(string? body)
    {
        if (string.IsNullOrWhiteSpace(body))
        {
            return Results.Problem(
                title: MissingBodyTitle,
                detail: MissingBodyDetail,
                statusCode: StatusCodes.Status400BadRequest);
        }

        CreateUserRequest? request;
        try
        {
            request = JsonSerializer.Deserialize<CreateUserRequest>(body, BodyJsonOptions);
        }
        catch (JsonException)
        {
            return Results.Problem(
                title: MalformedBodyTitle,
                detail: MalformedBodyDetail,
                statusCode: StatusCodes.Status400BadRequest);
        }

        if (request is null)
        {
            return Results.Problem(
                title: MalformedBodyTitle,
                detail: MalformedBodyDetail,
                statusCode: StatusCodes.Status400BadRequest);
        }

        var errors = Validator.ValidateFields(request);
        if (errors.Count > 0)
        {
            return Results.ValidationProblem(
                errors,
                title: InvalidRequestTitle,
                statusCode: StatusCodes.Status400BadRequest);
        }

        return Results.Ok(new CreateUserResponse(request.Email!, request.Name!, request.Age));
    }
}

