using System.Text.Json;
using Example;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace Example.Tests;

/// <summary>Tests for <see cref="Validator"/>, <see cref="CreateUserEndpoint"/>, and <see cref="FileResolver"/>.</summary>
public class ValidationTests
{
    private static readonly JsonSerializerOptions _responseJson = new(JsonSerializerDefaults.Web);

    /// <summary>Verifies that a valid request produces no errors.</summary>
    [Fact]
    public void AcceptsValidRequest()
    {
        var errors = Validator.Validate(new CreateUserRequest("a@b.co", "Ada", 30));
        Assert.Empty(errors);
    }

    /// <summary>Verifies that a missing email is rejected.</summary>
    [Fact]
