75: {
76:     /// <summary>Problem title used when the request body is absent.</summary>
77:     public const string MissingBodyTitle = "Missing request body";
78: 
79:     /// <summary>Problem detail used when the request body is absent.</summary>
80:     public const string MissingBodyDetail = "A JSON create-user request body is required.";
81: 
82:     /// <summary>Problem title used when the request body is not a valid create-user payload.</summary>
83:     public const string MalformedBodyTitle = "Malformed request body";
84: 
85:     /// <summary>Problem detail used when the request body is not a valid create-user payload.</summary>
86:     public const string MalformedBodyDetail = "The request body must be a JSON object with email, name, and optional age fields.";
87: 
88:     /// <summary>Problem title used when the payload fails validation.</summary>
89:     public const string InvalidRequestTitle = "Invalid create-user request";
90: 
91:     /// <summary>JSON contract used to read the request body.</summary>
92:     public static readonly JsonSerializerOptions BodyJsonOptions = new(JsonSerializerDefaults.Web);
93: 
94:     /// <summary>Handles a create-user request body.</summary>
95:     /// <param name="body">Raw JSON body received by the endpoint.</param>
96:     /// <returns>200 with the accepted payload; 400 problem details for missing, malformed, or invalid input.</returns>
97:     public static IResult Handle(string? body)
98:     {
99:         if (string.IsNullOrWhiteSpace(body))
100:         {
101:             return Results.Problem(
102:                 title: MissingBodyTitle,
103:                 detail: MissingBodyDetail,
104:                 statusCode: StatusCodes.Status400BadRequest);
105:         }
106: 
107:         CreateUserRequest? request;
108:         try
109:         {
110:             request = JsonSerializer.Deserialize<CreateUserRequest>(body, BodyJsonOptions);
111:         }
112:         catch (JsonException)
113:         {
114:             return Results.Problem(
115:                 title: MalformedBodyTitle,
116:                 detail: MalformedBodyDetail,
117:                 statusCode: StatusCodes.Status400BadRequest);
118:         }
119: 
120:         if (request is null)
121:         {
122:             return Results.Problem(
123:                 title: MalformedBodyTitle,
124:                 detail: MalformedBodyDetail,
125:                 statusCode: StatusCodes.Status400BadRequest);
126:         }
127: 
128:         var errors = Validator.ValidateFields(request);
129:         if (errors.Count > 0)
130:         {
131:             return Results.ValidationProblem(
132:                 errors.ToDictionary(pair => pair.Key, pair => pair.Value),
133:                 title: InvalidRequestTitle,
134:                 statusCode: StatusCodes.Status400BadRequest);
135:         }
136: 
137:         return Results.Ok(new CreateUserResponse(request.Email!, request.Name!, request.Age));
138:     }
139: }
